export const reportsCompletion = true;
export default function scene(rise) {
  const { lib } = rise;
  const plane = lib.axes({ x: [-1.5, 8], y: [-1.5, 1.5] }, { labels: false });
  const ring = Array.from({ length: 97 }, (_, i) => [Math.cos((i * Math.PI) / 48), Math.sin((i * Math.PI) / 48)]);
  const arm = lib.vector({ x: 1, y: 0, t: 0 });
  const wave = { to: 0 };
  return {
    frame() {
      lib.clear();
      lib.grid(plane, { step: 0.5 });
      plane.draw();
      lib.plot(plane, ring, { color: lib.color('muted') });
      arm.draw(plane);
      const angle = arm.angle;
      if (wave.to > 0) {
        const traced = Array.from({ length: 121 }, (_, i) => { const s = (angle * i) / 120; return [1.5 + s, Math.sin(s)]; });
        lib.plot(plane, traced, { to: wave.to });
        lib.line(plane, [Math.cos(angle), Math.sin(angle)], [1.5 + angle, Math.sin(angle)], { color: lib.color('highlight', 0.6), dash: [4, 6] });
        lib.point(plane, [1.5 + angle, Math.sin(angle)]);
      }
    },
    cue(name, { instant }) {
      if (name === 'arm') return lib.tween(arm, { t: 1 }, { ms: 900, instant });
      if (name === 'quarter') return lib.tween(arm, { angle: Math.PI / 2 }, { ms: 1500, instant });
      if (name === 'trace') {
        wave.to = 1;
        return lib.tween(arm, { angle: Math.PI * 2 }, { ms: 6000, instant }).then(() => rise.done());
      }
    }
  };
}
